def run_main(argv, capsys, runner=None, disk=None, later=LATER):
    rc = dc.main(
        argv,
        runner=runner or FakeRunner({"lsof": GOOD_LSOF}),
        now=time.time() + later,
        disk_usage=disk,
    )
    out = capsys.readouterr().out
